        "gl.toc.day2": "Tag 2", "gl.toc.day3": "Tag 3", "gl.toc.day4": "Tag 4", "gl.toc.day5": "Tag 5",
        "gl.toc.day6": "Tag 6", "gl.toc.day7": "Tag 7", "gl.toc.day8": "Tag 8", "gl.toc.day9": "Tag 9",
